          "stem": "默写与运用。\n（ 1 ）醉里挑灯看剑， ______ 。（辛弃疾《破阵子 • 为陈同甫赋壮词以寄之》）\n（ 2 ）枯藤老树昏鸦， ______ 。（马致远《天净沙 • 秋思》）\n（ 3 ） ______ ，在乎山水之间也。（欧阳修《醉翁亭记》）\n（ 4 ）小张去夏日西湖游玩时，看见了美丽的花朵，浅浅的草坪，他可以用（白居易《钱塘湖春行》）中的 “______ ，\n______” 两句来表示。",
