          "answer": "答案：\n（ 1 ）梦回吹角连营（注意 “ 华 ” 的书写）\n（ 2 ）小桥流水人家\n（ 3 ）醉翁之意不在酒\n（ 4 ）乱花渐欲迷人眼   浅草才能没马蹄（注意 “ 蹄 ” 的书写）",
          "explanation": "本题考查学生对古诗文名句的识记能力。解答此类题目，我们需要在平时的学习中，做好积累，根据提示语句写出相应的句子，尤\n其要注意不能出现错别字。理解性识记，注意结合语境填充。",
