          "category": "古诗文默写",
          "stem": "（一）默写（15分）\n1.会当凌绝顶，[[u]]                   [[/u]]。                （杜甫《望岳》》 六上\n2.草枯鹰眼疾，[[u]]                   [[/u]]。                （王维《观猎》）九上\n3.狼不敢前，[[u]]                      [[/u]]。                 （蒲松龄《狼》）八下\n4.[[u]]                  [[/u]]，竭其庐之入……                （柳宗元《捕蛇者说》九下\n5.枯藤老树昏鸦，[[u]]              [[/u]]，古道西风瘦马。  （马致远《天净沙·秋思》）八下",
          "answer": "1.一览众山小  2.雪尽马蹄轻  3.眈眈相向  4.殚其地之出  5.小桥流水人家",
          "explanation": "试题分析：本题考查学生根据上下句提示默写古诗、词、曲、文句子的能力，难度较小，一般错在汉字书写上。往年考试一般是一到两句文章，其余为诗词曲，两个默写上句，三个默写下句。今年只有一个默写上句，难度不大。\n易错字，一是字形相近（如“戊”“戌”和“戍”“匹马戍梁州”），二是音同、音近（如“留取丹心照汗青”的“汗”写成了“汉”），三是字词理解错误（“身老沧洲”的“洲”容易写成“州”，这个错误综合了前三项易错点，“洲”为水中陆地，大陆，而“州”是行政区域。“沧洲”是滨水的地方。古时常用以称隐士的居处。沧州市，简称“沧”，是河北省辖市，因东临渤海而得名，意为沧海之州），四是因语言习惯干扰出错（如“身世浮沉雨打萍”中的“浮沉”写成“沉浮”，巧记作者最终沉水，所以是“浮沉”），   \n注意易错字的写法：要根据句子的语境判断汉字，是形声字，根据形旁声旁来判断正确的写法。\n【考点定位】默写常见的名句名篇。能力层级为识记A。",
