          "type": "written",
          "category": "阅读理解",
          "stem": "（二）阅读下面两首诗，完成第6-7题（4分）两首诗歌都是六下\n送友人                                黄鹤楼\n李白                                  崔颢\n青山横北郭，白水绕东城。             昔人已乘黄鹤去，此地空余黄鹤楼。\n此地一为别，孤蓬万里征。             黄鹤一去不复返，白云千载空悠悠。\n浮云游子意，落日故人情。             晴川历历汉阳树，芳草萋萋鹦鹉洲。\n挥手自兹去，萧萧班马鸣。             日暮乡关何处是？烟波江上使人愁。\n\n6.两首诗都写到愁情：《送友人》写送别友人的愁情，《黄鹤楼》写的[[u]]        [[/u]]愁情。（2分）\n7.以下对两首诗的理解正确的一项是（     ）（2分）\nA.“万里”“千载”都有悠远之意。\nB.“故人”“昔人”都指曾经的老朋友。\nC.“青山”“晴川”都写了山色秀美之景。\nD.“浮云”“白云”都暗示诗人漂泊的身世。",
          "answer": "6.思乡     7.A",
          "explanation": "6.本题考查诗歌情感，根据日暮乡关何处是可以判断出思乡之情。\n    第一题常考的是文学常识，词语解释，内容理解，诗句情感等。\n7.A.“万里”是空间上的远，“千载”是时间上的远。B.“故人”是老朋友。“昔人”是指过去的仙人，非作者的朋友。C.“青山”写了山色秀美之景。“晴川历历汉阳树”：如今阳光照耀下的汉阳树木清晰可见，过去的时光一去不复返。“晴川”写物是人非之感。D.“浮云”是喻指远行的友人。白云千载空悠悠：千百年来只看见悠悠的白云。唯有悠悠白云仍然千载依旧。“白云”指白云悠悠，仙去楼空，岁月不再，物是人非，世事茫茫。\n故选A\n\n\n近五年中考\n2018年《饮湖上初晴后雨》\n（1）文学常识作者的号[填空题] \n（2）诗句内容理解[选择题]\n2017年《四块玉·别情》（17年题目和前几年比有什么变化？出现了文学常识）\n（1）文学常识作者是谁[填空题] \n（2）诗句内容理解[选择题]\n2016《卖炭翁》\n（1）诗句内容理解[填空题] \n（2）诗句内容理解[选择题]\n2015《丑奴儿·书博山道中壁》 《江城子·密州出猎》    《望岳》 \n（1）诗句情感理解[填空题] \n（2）诗句内容理解[选择题]  \n2014《破阵子·为陈同甫赋壮词以寄》 【八年级上】 \n（1）题目意思理解（写作目的）[填空题]\n（2）诗句感情理解[填空题]",
