          "type": "written",
          "category": "阅读理解",
          "stem": "（三）阅读下文，完成第8-10题（9分）\n金溪民方仲永，世隶耕。仲永生五年，未尝识书具，忽啼求之。父异焉，借旁近与之，即书诗四句，并自为其名。其诗以养父母、收族为意，传一乡秀才观之。自是指物作诗立就，其文理皆有可观者。邑人奇之，[[u]]稍稍宾客其父[[/u]]，或以钱币乞之。父利其然也，日扳仲永环谒于邑人，不使学。\n余闻之也久。明道中，从先人还家，于舅家见之，十二三矣。令作诗，不能称前时之闻。又七年，还自扬州，复到舅家问焉。曰：“泯然众人矣。”\n王子曰：仲永之通悟，受之天也。其受之天也，贤于材人远矣。卒之为众人，则其受于人者不至也。彼其受之天也，如此其贤也，不受之人，且为众人；今夫不受之天，固众人，又不受之人，得为众人而已耶？\n\n8.本文作者是[[u]]            [[/u]]（人名）。（2分）\n9.用现代汉翻译下面的句子。（3分）\n稍稍宾客其父\n[[u]]                                                                                [[/u]]\n10.本文记叙了仲永从五岁就能作诗到最终“[[u]]                        [[/u]]”的变化过程，表达了作者 [[u]]                                 [[/u]]的情感。（4分）",
          "answer": "8. 王安石    9. （同乡人）渐渐用宾客的礼节款待他的父亲    \n10.     (1). 泯然众人    (2). 痛惜",
          "explanation": "【8题详解】\n文学常识的考核主要集中在中外的作家、作品、文学现象、文学流派、文体知识等。重点记忆课本涉及到的和经典阅读中列出的作品。平时注意积累，理出线索，形成体系。死记硬背作者名字、书名及书中的重要人物的名字。此题考查的是与王安石有关的文学常识。《伤仲永》的作者是北宋文学家、政治家王安石。\n【9题详解】\n本题考查学生对文言句子的翻译能力。翻译文言语句是文言文阅读的必考题。课内翻译靠的是死记硬背，忘记的话根据直译为主，意译为辅的方式。逐字逐句翻译，翻译不通的考虑特殊句式，通假字等。翻译第一注意的是省略，第二注意动词翻译准确。注意“宾客”：名词意动用法，以……为宾客。把……当作宾客，也就是用宾客的礼节款待。\n【10题详解】\n一空，考查对文章重要信息的提取能力。在准确理解词意、句意、段意的基础上，梳理各句之间的内在联系，依据题干要求提取重要信息。如仲永最终的结局可提取“泯然众人”作为答案。二空，考查作者通过这件事所要抒发的情感。从标题“伤仲永”及仲永结局分析，表达作者对天才的荒废的惋惜之情；为像仲永的父亲这样不重视后天教育，思想落后的人而感到可悲。所以可概括为“痛惜”二字。\n译文：\n　　金溪平民方仲永，世代从事农业生产。仲永长到五岁，不曾认识笔、墨、纸、砚，（有一天）忽然放声哭着要这些东西；父亲对此感到诧异，从邻近人家借来给他，（仲永）马上写了四句诗，并且在诗后署上自己的名字。这首诗把奉养父母、团结同宗族的人作为内容，传阅于全乡的学识优秀的士人观赏。从此，（有人）指定物品（让他）作诗，（他能）立即写好，诗的文采和道理都有值得看的地方。同乡的人对他“指物作诗”感到非常惊奇，渐渐用宾客的礼节款待他的父亲，有的人（还）花钱讨取仲永的诗作。他的父亲认为这样有利可图，（就）每天拉着仲永四处拜访同乡的人，不让（他）学习。 \n　　我听到这件事很久了。明道年间，我随先父回到家乡，在舅舅家里见到他，（这时，他已经）十二三岁了。让（他）作诗，（写出来的诗已经）不能与从前的传闻相称了。又过了七年，（我）从扬州回来，再次到舅舅家，问起方仲永的情况，回答说：“（他的特异之处已经）消失净尽，成为普通的人了。” \n\n近五年中考\n课内文言文阅读    （14-15年课内文言文8分   2016-2018年9分 句子翻译课外文言文变成选择，课内不变）\n2018《小石潭记》\n（1）内容理解[选择题][2分]（2）句子翻译[填空题][3分]（3）内容理解[填空题][4分] \n2017年《登泰山记（节选）》\n（1）文学常识，选择[2分]（2）句子翻译[填空题][3分]（3）内容理解[填空题][4分] \n2016《捕蛇者说》\n（1）文学常识（作者）[2分] （2）句子翻译[填空题][3分]（3）内容理解[选择题][4分] \n2015《核舟记》\n  （1）文学常识、词语解释、句子翻译[填空题][6分]（2）文段中内容理解[选择题][2分]  \n2014《为学》 《论语》\n （1）文学常识[填空题][2分] （2）文章内容与中心的理解[填空题][6分]",
          "review": {
            "status": "pending"
          }
