          "type": "written",
          "category": "古诗文默写",
          "stem": "（一）默写（16分）\n1.清晨入古寺，[[u]] [[/u]][[u]]       [[/u]][[u]]          [[/u]][[u]]   [[/u]]。  常建《题破山寺后禅院》\n2.青山横北郭，[[u]] [[/u]][[u]]       [[/u]][[u]]          [[/u]][[u]]   [[/u]]。李白《送友人》\n3.相见时难别亦难，[[u]] [[/u]][[u]]       [[/u]][[u]]          [[/u]][[u]]   [[/u]]。李商隐《无题》\n4.其必曰:“[[u]] [[/u]][[u]]       [[/u]][[u]]          [[/u]][[u]]   [[/u]]，后天下之乐而乐”乎！ 范仲淹《岳阳楼记》\n5.纪录片《航拍中国》有一组镜头展现了祖国秋季的绚丽色彩，我们可用白朴《天净沙秋》中的句子“[[u]] [[/u]][[u]]       [[/u]][[u]]          [[/u]][[u]]   [[/u]]，[[u]] [[/u]][[u]]       [[/u]][[u]]          [[/u]][[u]]   [[/u]]”为画面配字幕。",
          "answer": "1. 初日照高林\n\n2. 白水绕东城。\n\n3. 东风无力百花残。\n\n4. 先天下之忧而忧\n\n5. 青山绿水，白草红叶黄花\n（二）（12分）",
