          "answer": "B",
          "explanation": "A.蒸馏水由一种物质（水）组成，属于纯净物，不属于溶液故A错；\nB.矿泉水含有水和多种矿物质，矿物质均匀分散在水中，形成均一，稳定的混合物，属于溶液，故B正确；\nC.豆浆中的不溶性固体小颗粒悬浮在水中，属于悬浊液，静置后会分层或沉淀，故C错；\nD.牛奶中的脂肪球等成分分散在水中形成的是乳浊液，静置后会分层，不属于溶液，故D错。\n故选：B。",
