          "stem": "下列选项中属于有机物的是（ ）",
          "answer": "C",
          "explanation": "有机物通常是含碳元素的化合物，但是碳的单质、碳的氧化物、碳酸、碳酸盐等的化学性质与无机物的化学性质相似，通常归为无\n机物；氯化钠、氯化钾不含碳元素，是无机物；碳酸含碳元素，但性质与无机物类似，属于无机物；葡萄糖含有碳、氢、氧元素，\n属于有机物。\n故选：C。",
